#!/usr/bin/env bash
set -euo pipefail
IP=193.122.155.227
remote () 
{ 
    local opts=(-o StrictHostKeyChecking=accept-new -o ConnectTimeout=15 -o ServerAliveInterval=30 -o BatchMode=yes -o ExitOnForwardFailure=yes -i "$HOME/.ssh/lambda_ed25519");
    if [[ $1 == --tunnel ]]; then
        ssh "${opts[@]}" -N -L "127.0.0.1:$PORT:127.0.0.1:8000" "ubuntu@$IP" < /dev/null > "$CACHE/tunnel.log" 2>&1 & TUNNEL=$!;
    else
        ssh "${opts[@]}" "ubuntu@$IP" "$@";
    fi
}
